// Questions de connaissance publiées pour l'examen civique « carte de séjour
// pluriannuelle » (CSP). Les choix sont pédagogiques ; à l'examen, une seule
// réponse est correcte parmi quatre propositions.
// Source de la liste : https://formation-civique.interieur.gouv.fr/examen-civique/liste-officielle-des-questions-de-connaissance-csp/

const SOURCES = {
  principes: "https://formation-civique.interieur.gouv.fr/fiches-par-thematiques/",
  institutions: "https://formation-civique.interieur.gouv.fr/fiches-par-thematiques/systeme-institutionnel-et-politique/",
  droits: "https://formation-civique.interieur.gouv.fr/fiches-par-thematiques/droits-et-devoirs/",
  histoire: "https://formation-civique.interieur.gouv.fr/fiches-par-thematiques/histoire-geographie-et-culture/",
  vivre: "https://formation-civique.interieur.gouv.fr/fiches-par-thematiques/vivre-dans-la-societe-fran%C3%A7aise/",
};

function question(id, topic, q, options, fact, source, trap = false) {
  return {
    id, q, topic, options, correct: 0,
    expl: `${fact} [Référence officielle](${SOURCES[source]}).`,
    trap,
  };
}

